import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"System Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"system-requirements/index.md","filePath":"system-requirements/index.md"}'),n={name:"system-requirements/index.md"};function s(o,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h1><p>TransferBook+ is a browser-based transportation operating platform. The requirements below help customers prepare their devices and help technical teams evaluate hosting readiness.</p><div class="warning custom-block"><p class="custom-block-title">Compatibility and capacity status</p><p>These are planning recommendations, not a certified minimum specification or a guarantee of commercial availability. The application source reviewed for this guide is v0.7.13. Actual support depends on the accepted deployment, enabled features, access permissions and compatibility testing.</p></div><h2 id="customer-devices-and-browsers" tabindex="-1">Customer devices and browsers <a class="header-anchor" href="#customer-devices-and-browsers" aria-label="Permalink to &quot;Customer devices and browsers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Recommended planning baseline</th></tr></thead><tbody><tr><td>Desktop operating system</td><td>A vendor-supported Windows, macOS or Linux release</td></tr><tr><td>Mobile operating system</td><td>A vendor-supported Android or iOS release</td></tr><tr><td>Web browser</td><td>Current stable Chrome, Edge, Firefox or Safari, as available for the device</td></tr><tr><td>Office workstation</td><td>Modern dual-core or better CPU; 8 GB RAM</td></tr><tr><td>Dispatcher display</td><td>1920 × 1080 or larger; keyboard and mouse recommended</td></tr><tr><td>Mobile device</td><td>Touchscreen, supported browser and reliable mobile data or Wi-Fi</td></tr><tr><td>Connectivity</td><td>Reliable broadband or mobile data; backup connection recommended for dispatch</td></tr><tr><td>Browser settings</td><td>JavaScript and necessary first-party cookies enabled; HTTPS access</td></tr></tbody></table><p>A native application installation is not required for browser-based access. The browser and device combinations above are candidates for compatibility validation, not a list of certified platforms. Do not assume offline operation, background tracking, push notifications or native-app availability.</p><h2 id="requirements-by-role" tabindex="-1">Requirements by role <a class="header-anchor" href="#requirements-by-role" aria-label="Permalink to &quot;Requirements by role&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Preparation</th></tr></thead><tbody><tr><td>Company administrator</td><td>Desktop or laptop, authorized account, access to company settings</td></tr><tr><td>Dispatcher</td><td>Desktop or laptop with a sufficiently large display, dependable internet, assigned permissions and configured operating data</td></tr><tr><td>Chauffeur</td><td>Charged mobile device, reliable connectivity and assigned account; location permissions only when an enabled feature requires them</td></tr><tr><td>Commercial partner</td><td>Supported browser and authorized partner access, where available</td></tr><tr><td>Passenger</td><td>Browser-capable device and an enabled public booking channel; no operator account assumed</td></tr></tbody></table><p>Passenger email is not a mandatory requirement for quick bookings. Use a permitted contact method without inventing email addresses. See <a href="/tutorials/phone-only-booking.html">phone-only booking</a> and <a href="/plus/passenger-information.html">passenger information</a>.</p><h2 id="network-and-security" tabindex="-1">Network and security <a class="header-anchor" href="#network-and-security" aria-label="Permalink to &quot;Network and security&quot;">​</a></h2><ul><li>Access the authorized deployment through HTTPS and keep the operating system and browser updated.</li><li>Use individual accounts and role-based access. Do not share credentials.</li><li>Permit HTTPS access to the approved application and any explicitly enabled third-party service endpoints; do not disable firewalls or certificate verification to resolve connectivity problems.</li><li>Use device screen locking and avoid storing passenger records on unmanaged devices.</li><li>Confirm that system clocks, time zones and browser settings are correct. For interrupted submissions, verify whether the reservation or payment already exists before retrying.</li><li>Use only synthetic passenger information in approved training or staging environments.</li></ul><p>See <a href="/developers/authentication.html">authentication and tenant access</a>, <a href="/developers/permissions.html">roles and permissions</a> and <a href="/help/access-and-session.html">access and session errors</a>.</p><h2 id="server-and-hosting-requirements" tabindex="-1">Server and hosting requirements <a class="header-anchor" href="#server-and-hosting-requirements" aria-label="Permalink to &quot;Server and hosting requirements&quot;">​</a></h2><p>This section is for hosting and technical teams, not ordinary customers. A managed deployment does not require customers to install Node.js or PostgreSQL on their workstations. Dedicated or self-hosted deployment is subject to separate approval, supported release packaging and operational readiness; this guide does not establish a commercial self-hosting offer.</p><table tabindex="0"><thead><tr><th>Component</th><th>Proposed evaluation baseline</th></tr></thead><tbody><tr><td>Operating system</td><td>Supported 64-bit Linux</td></tr><tr><td>CPU</td><td>4 vCPU</td></tr><tr><td>RAM</td><td>8 GB</td></tr><tr><td>Storage</td><td>80 GB SSD/NVMe with capacity monitoring</td></tr><tr><td>Application runtime</td><td>Node.js 24 LTS reference; confirm the exact supported runtime against the release</td></tr><tr><td>Database</td><td>PostgreSQL 16 reference; confirm version and migrations against the release</td></tr><tr><td>Reverse proxy</td><td>Apache or NGINX with TLS termination</td></tr><tr><td>Service management</td><td>Supervised application process with health monitoring</td></tr><tr><td>Email and external services</td><td>Approved credentials and connectivity only for enabled integrations</td></tr><tr><td>Backups</td><td>Automated, protected database and application backups; tested restoration</td></tr></tbody></table><p>The source reviewed uses a React/TypeScript frontend, Node.js/Express API and PostgreSQL client. Hardware estimates are starting points only. No capacity, concurrency, latency or uptime guarantee has been established by this guide.</p><h3 id="deployment-prerequisites" tabindex="-1">Deployment prerequisites <a class="header-anchor" href="#deployment-prerequisites" aria-label="Permalink to &quot;Deployment prerequisites&quot;">​</a></h3><ul><li>Release-specific build and migration instructions, validated artifacts and a documented rollback plan.</li><li>Least-privilege service and database accounts; secrets and signing keys protected outside public web content and source control.</li><li>Valid DNS and TLS, a correctly configured reverse proxy, restricted database access, health checks and operational logging.</li><li>Independent production, staging and demo environments; never use staging as an implicit production target.</li><li>Backups with retention and restore tests; monitoring for errors, disk space, database capacity and certificate expiry.</li><li>Separate approval and end-to-end testing for payment providers, notifications, external dispatch, mapping or AI integrations before activation.</li></ul><h2 id="compatibility-and-capacity-acceptance" tabindex="-1">Compatibility and capacity acceptance <a class="header-anchor" href="#compatibility-and-capacity-acceptance" aria-label="Permalink to &quot;Compatibility and capacity acceptance&quot;">​</a></h2><p>Before publishing certified requirements, validate the exact release on the intended devices and browser versions. Test sign-in and session expiry, reservation entry (including optional passenger email), scheduling and dispatch, role restrictions, mobile chauffeur workflows, interrupted network recovery and enabled integrations. Measure resource use and response times under representative peak booking and dispatch workloads, and test backup restoration. Record the tested versions, results and limitations with the relevant release.</p><p>For operational readiness, see <a href="/integrations/activation-and-channels.html">Integration readiness and channels</a> and <a href="/release-notes/">Release Notes</a>.</p><p><a href="/el/system-requirements/">Ελληνικά</a></p><p>For onboarding and the deployment lifecycle, see <a href="/installation/">Installation &amp; Deployment</a>.</p>',23)])])}const u=t(n,[["render",s]]);export{h as __pageData,u as default};
